Kad6StreamTransportAdapter::Kad6StreamTransportAdapter(const M2AParentPort& parent) noexcept{
    const auto* state=static_cast<const LT5StreamStateBinding*>(parent.context);
    if(state&&state->exit_streams&&state->origin_streams&&state->send_credits&&state->receive_credits&&state->streams_by_circuit&&state->next_generation){m_exit=state->exit_streams;m_origin=state->origin_streams;m_send=state->send_credits;m_receive=state->receive_credits;m_circuits=state->streams_by_circuit;m_nextGeneration=state->next_generation;}
}
bool Kad6StreamTransportAdapter::Register(std::uint32_t c,std::uint64_t s){if(!m_circuits||!m_send||!m_receive||!c||!s)return false;auto found=m_circuits->find(c);if(found!=m_circuits->end()&&found->second.count(s))return false;auto& members=(*m_circuits)[c];auto& send=(*m_send)[c];auto& receive=(*m_receive)[c];if(send.RegisterStream(s)!=kad6::Kad6Status::Ok||receive.RegisterStream(s)!=kad6::Kad6Status::Ok){send.RemoveStream(s);receive.RemoveStream(s);if(members.empty()){m_circuits->erase(c);m_send->erase(c);m_receive->erase(c);}return false;}members.insert(s);return true;}
void Kad6StreamTransportAdapter::Remove(std::uint32_t c,std::uint64_t s) noexcept{auto members=m_circuits->find(c);if(members==m_circuits->end())return;auto send=m_send->find(c);if(send!=m_send->end())send->second.RemoveStream(s);auto receive=m_receive->find(c);if(receive!=m_receive->end())receive->second.RemoveStream(s);members->second.erase(s);if(members->second.empty()){m_circuits->erase(members);m_send->erase(c);m_receive->erase(c);}}
