bool Kad6StreamTransportAdapter::FindExit(std::uint64_t s,LiveTunnelExitStreamRuntime& out) const{if(!m_exit)return false;auto it=m_exit->find(s);if(it==m_exit->end())return false;out=it->second;return true;} bool Kad6StreamTransportAdapter::FindOrigin(std::uint64_t s,LiveTunnelOriginStreamRuntime& out) const{if(!m_origin)return false;auto it=m_origin->find(s);if(it==m_origin->end())return false;out=it->second;return true;}
