bool Kad6StreamTransportAdapter::CreateExit(std::uint64_t s,LiveTunnelExitStreamRuntime& v){if(!m_exit||!m_nextGeneration||m_exit->size()>=512||m_exit->count(s)||!Register(v.circ_id,s))return false;v.generation=(*m_nextGeneration)++;if(!v.generation)v.generation=(*m_nextGeneration)++;try{m_exit->emplace(s,v);}catch(...){Remove(v.circ_id,s);return false;}return true;} bool Kad6StreamTransportAdapter::CreateOrigin(std::uint64_t s,LiveTunnelOriginStreamRuntime& v){if(!m_origin||!m_nextGeneration||m_origin->size()>=512||m_origin->count(s)||!Register(v.circ_id,s))return false;v.generation=(*m_nextGeneration)++;if(!v.generation)v.generation=(*m_nextGeneration)++;try{m_origin->emplace(s,v);}catch(...){Remove(v.circ_id,s);return false;}return true;}
