bool Kad6StreamTransportAdapter::TakeExit(std::uint64_t s,CKad6ExitSocket* p,std::uint64_t g,LiveTunnelExitStreamRuntime& out){if(!FindExit(s,p,out)||out.generation!=g)return false;m_exit->erase(s);Remove(out.circ_id,s);return true;} bool Kad6StreamTransportAdapter::TakeOrigin(std::uint64_t s,CKad6OriginSocket* p,std::uint64_t g,LiveTunnelOriginStreamRuntime& out){if(!FindOrigin(s,p,out)||out.generation!=g)return false;m_origin->erase(s);Remove(out.circ_id,s);return true;}
bool Kad6StreamTransportAdapter::HalfCloseExit(std::uint32_t c,const kad6::K6StreamHalfClose& v){if(!m_exit)return false;auto it=m_exit->find(v.stream_id);return it!=m_exit->end()&&it->second.circ_id==c&&it->second.flow.HalfClose(v)==kad6::Kad6Status::Ok;} bool Kad6StreamTransportAdapter::HalfCloseOrigin(std::uint32_t c,const kad6::K6StreamHalfClose& v){if(!m_origin)return false;auto it=m_origin->find(v.stream_id);return it!=m_origin->end()&&it->second.circ_id==c&&it->second.flow.HalfClose(v)==kad6::Kad6Status::Ok;}
